import React, { useState, useEffect, useRef, useCallback, memo } from 'react';
import { useGesture } from '@use-gesture/react';

// ── Custom keyboard shortcuts hook ──
const useKeyboardShortcuts = (handlers, deps = []) => {
  useEffect(() => {
    const handleKeyDown = (e) => {
      const key = e.key.toLowerCase();
      if (handlers[key]) handlers[key](e);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handlers, ...deps]);
};

// ── Hotspot Component ──
const Hotspot = memo(({ hotspot, onClick, zoomLevel }) => (
  <button
    className="absolute flex items-center justify-center w-12 h-12 text-3xl transition-all duration-200 border-2 border-blue-600 rounded-full shadow-xl cursor-pointer bg-white/70 hover:bg-white hover:scale-110"
    style={{
      left: `${hotspot.x}%`,
      top: `${hotspot.y}%`,
      transform: `translate(-50%, -50%) scale(${Math.max(0.6, 1 / zoomLevel)})`,
    }}
    onClick={(e) => onClick(hotspot, e)}
    title={hotspot.title}
    aria-label={`Hotspot: ${hotspot.title}`}
  >
    •
  </button>
));
Hotspot.displayName = 'Hotspot';

// ── Reusable Control Button ──
const ControlButton = memo(({ icon, onClick, title, className = '' }) => (
  <button
    onClick={onClick}
    className={`p-3.5 bg-black/70 backdrop-blur-lg text-white rounded-full hover:bg-black/90 transition-all shadow-xl hover:scale-110 ${className}`}
    title={title}
    aria-label={title}
  >
    {icon}
  </button>
));
ControlButton.displayName = 'ControlButton';

// ── Main Interactive Viewer ──
const InteractiveViewer = memo(({
  selectedLocation,
  locationMap,
  isFullscreen,
  setIsFullscreen,
  zoomLevel,
  setZoomLevel,
  showHotspots,
  setShowHotspots,
  showInfo,
  toggleInfo,
  audioEnabled,
  toggleAudio,
  viewMode,
  changeViewMode,
  isPlaying,
  chatOpen,
  setChatOpen,
  chatMessages,
  chatInput,
  setChatInput,
  handleChatSend,
}) => {
  const [rotation, setRotation] = useState({ yaw: 0, pitch: 0 });
  const viewerRef = useRef(null);
  const [currentHotspot, setCurrentHotspot] = useState(null);
  const [showCopiedToast, setShowCopiedToast] = useState(false);

  const loc = locationMap[selectedLocation] || {};

  // Gesture: drag + pinch + wheel
  const bind = useGesture(
    {
      onDrag: ({ down, movement: [mx, my], pinching }) => {
        if (pinching) return;
        setRotation((prev) => ({
          yaw: (prev.yaw + mx * 0.28) % 360,
          pitch: Math.max(-90, Math.min(90, prev.pitch - my * 0.28)),
        }));
      },

      onPinch: ({ offset: [d], last, origin: [ox, oy] }) => {
        if (last) return;
        setZoomLevel((prev) => Math.max(0.6, Math.min(4, prev * (1 + d * 0.004))));
        // Zoom-to-point logic can be added later if needed
      },

      onWheel: ({ event, pinching, delta: [, dy] }) => {
        if (pinching) return;
        event.preventDefault();
        setZoomLevel((p) => Math.max(0.6, Math.min(4, p - dy * 0.0018)));
      },
    },
    {
      drag: { filterTaps: true, preventScroll: true },
      pinch: { scaleBounds: { min: 0.6, max: 4 } },
      wheel: { preventDefault: true },
      target: viewerRef,
      enabled: true,
    }
  );

  const handleHotspotClick = useCallback((hotspot, e) => {
    e.stopPropagation();
    setCurrentHotspot(hotspot);
    const timer = setTimeout(() => setCurrentHotspot(null), 7000);
    return () => clearTimeout(timer);
  }, []);

  const handleShare = useCallback(async () => {
    const url = loc.url || window.location.href;
    if (navigator.share) {
      try {
        await navigator.share({ title: `${selectedLocation} Virtual Tour`, text: loc.description, url });
        return;
      } catch (err) {
        if (err.name !== 'AbortError') console.warn(err);
      }
    }
    try {
      await navigator.clipboard.writeText(url);
      setShowCopiedToast(true);
      setTimeout(() => setShowCopiedToast(false), 2200);
    } catch {}
  }, [selectedLocation, loc]);

  // Keyboard controls
  useKeyboardShortcuts(
    {
      arrowup: () => setRotation(p => ({ ...p, pitch: Math.max(-90, p.pitch - 7) })),
      arrowdown: () => setRotation(p => ({ ...p, pitch: Math.min(90, p.pitch + 7) })),
      arrowleft: () => setRotation(p => ({ ...p, yaw: (p.yaw - 7 + 360) % 360 })),
      arrowright: () => setRotation(p => ({ ...p, yaw: (p.yaw + 7) % 360 })),
      '+': () => setZoomLevel(p => Math.min(4, p + 0.25)),
      '-': () => setZoomLevel(p => Math.max(0.6, p - 0.25)),
      '0': () => { setZoomLevel(1); setRotation({ yaw: 0, pitch: 0 }); },
      escape: () => {
        setIsFullscreen(false);
        setCurrentHotspot(null);
        setChatOpen(false);
      },
      h: () => setShowHotspots(p => !p),
      i: toggleInfo,
      m: toggleAudio,
      f: () => setIsFullscreen(p => !p),
    },
    [setIsFullscreen, toggleInfo, toggleAudio]
  );

  return (
    <div
      ref={viewerRef}
      className="relative w-full h-full overflow-hidden bg-black select-none touch-none"
      {...bind()}
    >
      {/* 360° Background – GPU accelerated */}
      <div
        className="absolute inset-0 origin-center will-change-transform"
        style={{
          transform: `perspective(1400px) rotateX(${rotation.pitch}deg) rotateY(${rotation.yaw}deg) scale(${zoomLevel})`,
          backgroundImage: `url(${loc.image})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          imageRendering: zoomLevel > 1.8 ? 'crisp-edges' : 'auto',
        }}
      />

      {/* Hotspots */}
      {showHotspots && loc.hotspots?.map(hotspot => (
        <Hotspot
          key={hotspot.id}
          hotspot={hotspot}
          onClick={handleHotspotClick}
          zoomLevel={zoomLevel}
        />
      ))}

      {/* Hotspot Info Popup */}
      {currentHotspot && (
        <div
          className="absolute z-50 max-w-lg text-white transform -translate-x-1/2 -translate-y-1/2 border shadow-2xl top-1/2 left-1/2 bg-black/85 backdrop-blur-xl p-7 rounded-3xl border-white/10 animate-fadeIn"
          onClick={() => setCurrentHotspot(null)}
        >
          <button className="absolute text-2xl top-4 right-5 hover:text-gray-300" aria-label="Close">✕</button>
          <h3 className="mb-3 text-2xl font-bold">{currentHotspot.title}</h3>
          <p className="leading-relaxed text-gray-200">{currentHotspot.description}</p>
          <p className="mt-5 text-sm italic text-gray-500">Tap anywhere to close • Auto-closes in 7s</p>
        </div>
      )}

      {/* Top Controls (minimal in fullscreen) */}
      <div className={`absolute top-5 right-5 flex flex-col gap-4 z-30 ${isFullscreen ? 'scale-90 opacity-80' : ''}`}>
        <ControlButton icon={showHotspots ? "📍" : "📍 off"} onClick={() => setShowHotspots(p => !p)} title="Hotspots (H)" />
        <ControlButton icon={isFullscreen ? "⤢ exit" : "⛶ full"} onClick={() => setIsFullscreen(p => !p)} title="Fullscreen (F)" />
        <ControlButton icon="🔗" onClick={handleShare} title="Share Location" />
      </div>

      {/* Zoom Indicator */}
      <div className="absolute bottom-24 right-6 bg-black/70 backdrop-blur-md px-5 py-2.5 rounded-full text-white text-base font-medium z-30 shadow-lg">
        {Math.round(zoomLevel * 100)}%
      </div>

      {/* Bottom Hint Bar – hidden in fullscreen */}
      {!isFullscreen && (
        <div className="absolute flex items-center gap-6 px-8 py-4 text-sm text-white -translate-x-1/2 border rounded-full shadow-2xl bottom-5 left-1/2 bg-black/75 backdrop-blur-xl border-white/10">
          <span>🖱️ Drag / 📱 Pinch → Explore</span>
          <span className="opacity-70">•</span>
          <span>🔍 Scroll / Pinch → Zoom</span>
        </div>
      )}

      {/* Copied Toast */}
      {showCopiedToast && (
        <div className="fixed z-50 px-8 py-4 text-white -translate-x-1/2 rounded-full shadow-2xl bottom-10 left-1/2 bg-green-700/90 animate-fadeInOut">
          Link copied successfully!
        </div>
      )}

      {/* AI Chat Interface */}
      <div className="absolute z-40 bottom-28 left-6">
        {chatOpen ? (
          <div className="overflow-hidden border shadow-2xl w-80 sm:w-96 bg-gradient-to-br from-blue-950/95 to-indigo-950/95 backdrop-blur-2xl rounded-3xl border-blue-500/20">
            <div className="flex items-center justify-between p-4 border-b border-blue-500/20">
              <h3 className="text-lg font-semibold">Tour Guide AI</h3>
              <button onClick={() => setChatOpen(false)} className="text-2xl hover:text-gray-300">✕</button>
            </div>
            <div className="p-5 space-y-4 overflow-y-auto h-72 scrollbar-thin scrollbar-thumb-blue-600">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.isBot ? 'justify-start' : 'justify-end'}`}>
                  <div className={`max-w-[82%] px-5 py-3 rounded-2xl ${msg.isBot ? 'bg-blue-800/40' : 'bg-indigo-600/50'}`}>
                    {msg.text}
                  </div>
                </div>
              ))}
            </div>
            <form onSubmit={handleChatSend} className="flex gap-3 p-4 border-t border-blue-500/20">
              <input
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                placeholder="Ask anything about this place..."
                className="flex-1 px-5 py-3 text-white placeholder-gray-400 border rounded-full bg-black/50 border-blue-500/30 focus:outline-none focus:border-blue-400"
              />
              <button type="submit" className="px-6 font-medium bg-blue-600 rounded-full shadow-md hover:bg-blue-500">Send</button>
            </form>
          </div>
        ) : (
          <button
            onClick={() => setChatOpen(true)}
            className="flex items-center gap-3 py-4 text-base font-semibold transition-all border rounded-full shadow-2xl px-7 bg-gradient-to-r from-blue-600 to-indigo-600 hover:shadow-blue-600/50 hover:scale-105 border-blue-400/30"
          >
            💬 Ask AI Guide
          </button>
        )}
      </div>
    </div>
  );
});
InteractiveViewer.displayName = 'InteractiveViewer';

